import type { ComponentProps, ReactNode } from "react";

import { Badge } from "@rhs-ui/primitives/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@rhs-ui/primitives/table";
import { DiffRow, UnchangedFields } from "@rhs-ui/dashboard/field-diff-table/diff-rows";
import { ROW_GRID, describeValue, isEmptyValue, isLongText, kindOf, labelOf, type FieldChange, type FieldFormatter } from "@rhs-ui/dashboard/field-diff-table/diff";
import { cn } from "@/lib/utils";

export type { FieldChange, FieldChangeKind, FieldFormatter } from "@rhs-ui/dashboard/field-diff-table/diff";

export interface FieldDiffTableProps extends Omit<ComponentProps<"div">, "children"> {
  /** Every field of the record with its old and new value. Fields that did not change fold away on their own. */
  changes: readonly FieldChange[];
  /** Draw a field's values your way, by field name: a price as money, a date in your format. Called only for values that are not empty. */
  formatters?: Readonly<Record<string, FieldFormatter>>;
  /** Names the table for screen readers. */
  caption?: string;
  /** Lines of text shown before a long value is clamped behind "Show full text". */
  lines?: number;
  /** BCP 47 locale for numbers, dates and lists. */
  locale?: string;
  /** IANA zone for dates. */
  timeZone?: string;
}

/**
 * What changed on a record, for an audit trail, an approval screen or an
 * edit review: each field with its old and new value side by side. The old
 * value is struck through and muted and the new one is at full strength, so
 * the change reads in monochrome, and every row also reads in words ("Status:
 * was Draft, now Published"). A value that was empty says "was empty", one
 * that was cleared says "removed". Fields that did not change fold under "n
 * unchanged fields", and long text is clamped behind a "Show full text"
 * button that appears only when something is hidden. On a narrow container
 * the field takes a line of its own, and long text stacks old above new.
 * Formatters are plain functions, so the table renders on the server; only
 * the two buttons run in the browser.
 */
export function FieldDiffTable({
  changes,
  formatters,
  caption = "Changes to this record",
  lines = 3,
  locale = "en-US",
  timeZone = "UTC",
  className,
  ...props
}: FieldDiffTableProps) {
  const context = { locale, timeZone };
  const clamp = Math.max(1, Math.floor(lines));
  const draw = (change: FieldChange, value: unknown): ReactNode => {
    const formatter = formatters?.[change.field];
    if (formatter) return formatter(value, change);
    const { text, mono } = describeValue(value, context);
    return mono ? <code className="font-mono text-[0.8125rem]">{text}</code> : text;
  };

  const rows = changes.map((change) => ({ change, kind: kindOf(change), label: labelOf(change) }));
  const edits = rows.filter((row) => row.kind !== "unchanged");
  const unchanged = rows.filter((row) => row.kind === "unchanged");
  const added = edits.filter((row) => row.kind === "added").length;
  const removed = edits.filter((row) => row.kind === "removed").length;
  const edited = edits.length - added - removed;
  const detail = [edited > 0 && added + removed > 0 ? `${edited} edited` : "", added > 0 ? `${added} added` : "", removed > 0 ? `${removed} removed` : ""].filter(Boolean).join(" · ");

  return (
    <div data-slot="field-diff-table" className={cn("@container w-full min-w-0 overflow-hidden rounded-xl border border-border bg-card text-card-foreground", className)} {...props}>
      <div className="flex flex-wrap items-baseline gap-x-3 gap-y-0.5 border-b border-border px-4 py-3">
        <p className="text-sm font-medium tracking-[-0.01em]">{edits.length === 0 ? "No fields changed" : `${edits.length} ${edits.length === 1 ? "field" : "fields"} changed`}</p>
        {detail ? <p className="text-xs text-muted-foreground">{detail}</p> : null}
      </div>

      <Table role="table" aria-label={caption} className="block">
        {edits.length > 0 ? (
          <TableHeader role="rowgroup" className="block">
            <TableRow role="row" className={cn(ROW_GRID, "bg-muted/30 px-4 py-2 hover:bg-muted/30 @max-xl:sr-only")}>
              <TableHead role="columnheader" scope="col" className="h-auto p-0 text-xs">
                Field
              </TableHead>
              <TableHead role="columnheader" scope="col" className="h-auto p-0 text-xs">
                Before
              </TableHead>
              <TableHead role="columnheader" aria-hidden="true" className="h-auto p-0" />
              <TableHead role="columnheader" scope="col" className="h-auto p-0 text-xs">
                After
              </TableHead>
            </TableRow>
          </TableHeader>
        ) : null}

        <TableBody role="rowgroup" className="block">
          {edits.length === 0 ? (
            <TableRow role="row" className="block hover:bg-transparent">
              <TableCell role="cell" className="block px-4 py-8 text-center text-sm text-muted-foreground">
                Nothing differs between the two versions.
              </TableCell>
            </TableRow>
          ) : null}
          {edits.map(({ change, kind, label }) => (
            <DiffRow
              key={change.field}
              kind={kind}
              label={label}
              lines={clamp}
              stacked={isLongText(change.before) || isLongText(change.after)}
              field={
                <span className="flex flex-wrap items-center gap-x-2 gap-y-1">
                  <span className="text-[0.8125rem] leading-5 font-medium">{label}</span>
                  {kind === "added" ? <Badge variant="outline">Added</Badge> : kind === "removed" ? <Badge variant="muted">Removed</Badge> : null}
                </span>
              }
              before={
                isEmptyValue(change.before) ? (
                  <span className="text-muted-foreground italic">was empty</span>
                ) : (
                  <>
                    <span className="sr-only">was </span>
                    <del className="text-muted-foreground line-through decoration-muted-foreground/60 decoration-1">{draw(change, change.before)}</del>
                  </>
                )
              }
              after={
                <>
                  <span className="sr-only">now </span>
                  {isEmptyValue(change.after) ? (
                    <span className="text-muted-foreground italic">removed</span>
                  ) : (
                    <ins className="font-medium text-foreground no-underline">{draw(change, change.after)}</ins>
                  )}
                </>
              }
            />
          ))}
        </TableBody>

        {unchanged.length > 0 ? (
          <UnchangedFields count={unchanged.length}>
            {unchanged.map(({ change, kind, label }) => (
              <DiffRow
                key={change.field}
                kind={kind}
                label={label}
                lines={clamp}
                field={<span className="text-[0.8125rem] leading-5 font-medium">{label}</span>}
                after={isEmptyValue(change.after) && isEmptyValue(change.before) ? <span className="italic">Empty</span> : draw(change, isEmptyValue(change.after) ? change.before : change.after)}
              />
            ))}
          </UnchangedFields>
        ) : null}
      </Table>
    </div>
  );
}

import type { ReactNode } from "react";

/** What happened to a field. `unchanged` fields fold away under "n unchanged fields". */
export type FieldChangeKind = "changed" | "added" | "removed" | "unchanged";

export interface FieldChange {
  /** The field's identity, and the key `formatters` is read by: "status", "due_date". */
  field: string;
  /** What the field is called for a reader: "Due date". Without it the field name is tidied up ("due_date" becomes "Due date"). */
  label?: string;
  /** The value before the edit. Empty (`undefined`, `null`, `""` or `[]`) reads as "was empty". */
  before?: unknown;
  /** The value after the edit. Empty reads as "removed". */
  after?: unknown;
  /** What happened. Worked out from `before` and `after` when you leave it out. */
  kind?: FieldChangeKind;
}

/** Draws one value your way. It is only called for a value that is not empty. */
export type FieldFormatter = (value: unknown, change: FieldChange) => ReactNode;

/** The columns of a change row: field, before, an arrow, after. On a narrow container the field takes a line of its own. */
export const ROW_GRID = "grid grid-cols-[minmax(0,1fr)_1.5rem_minmax(0,1fr)] gap-x-2 gap-y-1.5 @xl:grid-cols-[minmax(8rem,11rem)_minmax(0,1fr)_2rem_minmax(0,1fr)] @xl:gap-x-3";

/** An empty value is not the same as zero or false: those are values. */
export function isEmptyValue(value: unknown): boolean {
  return value === undefined || value === null || (typeof value === "string" && value.trim() === "") || (Array.isArray(value) && value.length === 0);
}

function sameValue(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (a instanceof Date && b instanceof Date) return a.getTime() === b.getTime();
  if (typeof a === "object" && typeof b === "object" && a !== null && b !== null) {
    try {
      return JSON.stringify(a) === JSON.stringify(b);
    } catch {
      return false;
    }
  }
  return false;
}

/** The kind a change was given, or the one its two values imply. */
export function kindOf(change: FieldChange): FieldChangeKind {
  if (change.kind) return change.kind;
  const before = isEmptyValue(change.before);
  const after = isEmptyValue(change.after);
  if (before && after) return "unchanged";
  if (before) return "added";
  if (after) return "removed";
  return sameValue(change.before, change.after) ? "unchanged" : "changed";
}

/** "due_date" and "dueDate" both become "Due date". A label you gave is left alone. */
export function labelOf(change: FieldChange): string {
  if (change.label) return change.label;
  const words = change.field
    .replace(/([a-z\d])([A-Z])/g, "$1 $2")
    .replace(/[_\-.]+/g, " ")
    .trim()
    .toLowerCase();
  return words ? words.charAt(0).toUpperCase() + words.slice(1) : change.field;
}

export interface FormatContext {
  /** BCP 47 locale for numbers, dates and lists. */
  locale: string;
  /** IANA zone for dates. */
  timeZone: string;
}

/** A value as text, and whether it should be set in a monospace face (data rather than prose). */
export function describeValue(value: unknown, context: FormatContext): { text: string; mono: boolean } {
  const { locale, timeZone } = context;
  if (typeof value === "string") return { text: value, mono: false };
  if (typeof value === "number") return { text: Number.isFinite(value) ? new Intl.NumberFormat(locale).format(value) : String(value), mono: false };
  if (typeof value === "bigint") return { text: new Intl.NumberFormat(locale).format(value), mono: false };
  if (typeof value === "boolean") return { text: value ? "Yes" : "No", mono: false };
  if (value instanceof Date) {
    return {
      text: Number.isNaN(value.getTime()) ? "Invalid date" : new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "short", timeZone }).format(value),
      mono: false,
    };
  }
  if (Array.isArray(value)) {
    const items = value.map((item) => describeValue(item, context).text);
    return { text: new Intl.ListFormat(locale, { style: "narrow", type: "conjunction" }).format(items), mono: false };
  }
  if (typeof value === "object" && value !== null) {
    try {
      return { text: JSON.stringify(value), mono: true };
    } catch {
      return { text: String(value), mono: true };
    }
  }
  return { text: String(value), mono: false };
}

/**
 * Long prose, and a single long token such as an email address or an id, get a
 * line of their own for each side on a narrow container, where two columns
 * would be too thin to read and would break the token in the middle.
 */
export function isLongText(value: unknown): boolean {
  return typeof value === "string" && (value.length > 80 || value.includes("\n") || value.split(/\s+/).some((token) => token.length > 18));
}

"use client";

import { useId, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";

import { IconArrowDown, IconArrowRight, IconChevronDown, IconChevronRight } from "@rhs-ui/icons";
import { TableBody, TableCell, TableHead, TableRow } from "@rhs-ui/primitives/table";
import { ROW_GRID, type FieldChangeKind } from "@rhs-ui/dashboard/field-diff-table/diff";
import { cn } from "@/lib/utils";

/** The values arrive drawn: formatters are plain functions, so they run on the server, and only the two small interactions below run in the browser. */
export interface DiffRowProps {
  kind: FieldChangeKind;
  /** The field's name, for the toggle's accessible name. */
  label: string;
  /** The first cell: the name, and a badge for an added or removed value. */
  field: ReactNode;
  /** The old value. Leave it out for an unchanged field, which shows one value. */
  before?: ReactNode;
  /** The new value, or for an unchanged field its only value. */
  after: ReactNode;
  /** On a narrow container, put the old value above the new one instead of beside it. */
  stacked?: boolean;
  /** How many lines of text show before it is clamped. */
  lines: number;
}

const CELL = "min-w-0 p-0 text-sm leading-5 [overflow-wrap:anywhere]";
const CAPTION = "mb-0.5 block text-xs text-muted-foreground @xl:hidden";

/**
 * One field of the diff. A value of more than a few lines is clamped, and a
 * "Show full text" button appears only when something is actually hidden; it
 * opens both sides of the row together so they stay side by side.
 */
export function DiffRow({ kind, label, field, before, after, stacked = false, lines }: DiffRowProps) {
  const [expanded, setExpanded] = useState(false);
  const [clipped, setClipped] = useState(false);
  const beforeBox = useRef<HTMLDivElement>(null);
  const afterBox = useRef<HTMLDivElement>(null);
  const single = before === undefined;

  useLayoutEffect(() => {
    // Open, the text is all there; keep the button so it can be closed again.
    if (expanded) return;
    const boxes = [beforeBox.current, afterBox.current].filter((box): box is HTMLDivElement => box !== null);
    const measure = (): void => setClipped(boxes.some((box) => box.scrollHeight > box.clientHeight + 1));
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    for (const box of boxes) observer.observe(box);
    return () => observer.disconnect();
  }, [expanded]);

  const clamp: CSSProperties | undefined = expanded ? undefined : { display: "-webkit-box", WebkitBoxOrient: "vertical", WebkitLineClamp: lines, overflow: "hidden" };

  return (
    <TableRow role="row" data-kind={kind} className={cn(ROW_GRID, "items-start px-4 py-3", stacked && "@max-xl:grid-cols-1")}>
      <TableHead role="rowheader" scope="row" className="col-span-full h-auto p-0 text-left font-normal whitespace-normal text-foreground @xl:col-span-1">
        {field}
      </TableHead>
      {single ? (
        <TableCell role="cell" className={cn(CELL, "col-span-full @xl:col-span-3")}>
          <div ref={afterBox} style={clamp} className="whitespace-pre-line">
            {after}
          </div>
        </TableCell>
      ) : (
        <>
          <TableCell role="cell" className={CELL}>
            <span aria-hidden="true" className={CAPTION}>
              Before
            </span>
            <div ref={beforeBox} style={clamp} className="whitespace-pre-line">
              {before}
            </div>
          </TableCell>
          <TableCell role="cell" aria-hidden="true" className={cn("flex h-5 items-center p-0 text-muted-foreground", stacked ? "justify-start @xl:justify-center" : "justify-center")}>
            {stacked ? <IconArrowDown size={14} className="@xl:hidden" /> : null}
            <IconArrowRight size={14} className={stacked ? "hidden @xl:block" : undefined} />
          </TableCell>
          <TableCell role="cell" className={CELL}>
            <span aria-hidden="true" className={CAPTION}>
              After
            </span>
            <div ref={afterBox} style={clamp} className="whitespace-pre-line">
              {after}
            </div>
          </TableCell>
        </>
      )}
      {clipped ? (
        <TableCell role="cell" className="col-span-full p-0 @xl:col-span-3 @xl:col-start-2">
          <button
            type="button"
            aria-expanded={expanded}
            onClick={() => setExpanded((open) => !open)}
            className="inline-flex items-center gap-1 rounded-sm text-xs font-medium text-muted-foreground outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40"
          >
            {expanded ? "Show less" : "Show full text"}
            <span className="sr-only"> of {label}</span>
            <IconChevronDown size={12} aria-hidden="true" className={cn("motion-safe:transition-transform motion-safe:duration-150", expanded && "rotate-180")} />
          </button>
        </TableCell>
      ) : null}
    </TableRow>
  );
}

export interface UnchangedFieldsProps {
  /** How many fields are folded away. */
  count: number;
  /** The rows of the unchanged fields. */
  children: ReactNode;
}

/** The fields that did not change, folded under one line that says how many there are. */
export function UnchangedFields({ count, children }: UnchangedFieldsProps) {
  const [open, setOpen] = useState(false);
  const rows = useId();
  return (
    <>
      <TableBody role="rowgroup" className="block border-t border-border">
        <TableRow role="row" className="block">
          <TableCell role="cell" className="block p-0">
            <button
              type="button"
              aria-expanded={open}
              aria-controls={rows}
              onClick={() => setOpen((value) => !value)}
              className="flex w-full items-center gap-2 px-4 py-3 text-left text-[0.8125rem] font-medium text-muted-foreground outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-inset focus-visible:ring-ring/40"
            >
              <IconChevronRight size={14} aria-hidden="true" className={cn("shrink-0 motion-safe:transition-transform motion-safe:duration-150", open && "rotate-90")} />
              {count} unchanged {count === 1 ? "field" : "fields"}
            </button>
          </TableCell>
        </TableRow>
      </TableBody>
      <TableBody id={rows} role="rowgroup" hidden={!open} className={cn("border-t border-border bg-muted/30 text-muted-foreground", open ? "block" : "hidden")}>
        {children}
      </TableBody>
    </>
  );
}
